      "The tool must be reserved exclusively before use and released afterwards",
      "transport-tool must be executed by agvexecutor",
      "NR7 must be at st2 before configure-tool and tighten-fasteners",
      "The tightening program must come only from get-program",
      "Every tool-using Step depends on the reserve-tool Step (lease renewal)",
      "The operator explicitly requested that the quality check (evaluate-tightening) be skipped"
    ],
    "preference": "Minimize total execution time",
    "priority": "normal",
    "horizon": "This request only (single tightening job)",
    "requested_capabilities": [],
    "omit_services": ["evaluate-tightening"]
