          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "ReturnTool",
        "next": "ReleaseTool",
        "steps": [
          {"name": "to-crib", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}}
        ]
      },
      {
        "name": "ReleaseTool",
        "next": null,
        "steps": [
